#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <numpy/arrayobject.h>
#include <string.h>
#include <stdint.h>

/*
 * ARNAUD_dnaupd(state, resid, v, ipntr, workd, workl, lworkl)
 * state is a packed struct. Layout inferred from pack_dict_to_state_d
 * (doubles first, then ints) and from field offsets used inside ARNAUD_dnaupd.
 *
 * Confirmed offsets (from disassembly of ARNAUD_dnaupd):
 *   0x34 ido, 0x38 info, 0x44 n, 0x48 ncv, 0x4c nev, 0x60 ???(np?), 
 *   0x94, 0x9c
 * Doubles occupy 0x00..0x28 (5*8=40), so ints start at offset 40 = 0x28.
 *   ido  = 0x34 -> int index (0x34-0x28)/4 = 3
 *   info = 0x38 -> int index 4
 *   n    = 0x44 -> int index 7
 *   ncv  = 0x48 -> int index 8
 *   nev  = 0x4c -> int index 9
 *
 * Dict insertion order (5 doubles then ints):
 *   d0 tol, d1 getv0_rnorm0, d2 aitr_betaj, d3 aitr_rnorm1, d4 aitr_wnorm, d5 aup2_rnorm
 * That's 6 doubles = 48 bytes = 0x30. Then ido would be at 0x30, but disassembly
 * says ido at 0x34. So there is 4 bytes of padding OR the first field isn't tol.
 *
 * Try: 5 doubles (40 bytes) + pad 4? No. Let's just test empirically.
 *
 * We'll expose a function that takes the arrays and scalar params and tries a
 * candidate layout, returning ido/info after one call, so we can compare with scipy.
 */

extern void ARNAUD_dnaupd(void *state, double *resid, double *v, int *ipntr,
                          double *workd, double *workl, int lworkl);

typedef struct {
    double d[6];
    int i[64];
} State;

static PyObject *call_once(PyObject *self, PyObject *args) {
    /* args: n, nev, ncv, maxiter, tol, which, bmat, info, mode, shift,
              resid, v, ipntr, workd, workl, layout_id */
    int n, nev, ncv, maxiter, which, bmat, info, mode, shift, layout;
    double tol;
    PyObject *resid_o, *v_o, *ipntr_o, *workd_o, *workl_o;
    if (!PyArg_ParseTuple(args, "iiiiidiiiiiOOOOOi",
                          &n,&nev,&ncv,&maxiter,&which,&tol,&bmat,&info,&mode,&shift,
                          &layout, &resid_o,&v_o,&ipntr_o,&workd_o,&workl_o)) {
        return NULL;
    }
    double *resid = (double*)PyArray_DATA((PyArrayObject*)resid_o);
    double *v = (double*)PyArray_DATA((PyArrayObject*)v_o);
    int *ipntr = (int*)PyArray_DATA((PyArrayObject*)ipntr_o);
    double *workd = (double*)PyArray_DATA((PyArrayObject*)workd_o);
    double *workl = (double*)PyArray_DATA((PyArrayObject*)workl_o);

    State st;
    memset(&st, 0, sizeof(st));

    /* layout experiments */
    if (layout == 0) {
        /* 6 doubles then ints in dict order */
        st.d[0] = tol;
        int *ip = st.i;
        int idx = 0;
        ip[idx++] = 0;       /* ido */
        ip[idx++] = which;
        ip[idx++] = bmat;
        ip[idx++] = info;
        ip[idx++] = 0;       /* iter */
        ip[idx++] = maxiter;
        ip[idx++] = mode;
        ip[idx++] = n;
        ip[idx++] = 0;       /* nconv */
        ip[idx++] = ncv;
        ip[idx++] = nev;
        ip[idx++] = 0;       /* np */
        ip[idx++] = shift;
    } else if (layout == 1) {
        /* 5 doubles, then pad, then ints — put ido at byte 0x34 */
        st.d[0] = tol;
        unsigned char *base = (unsigned char*)&st;
        int *ido = (int*)(base + 0x34);
        ido[0] = 0;          /* ido */
        ido[1] = info;       /* 0x38 */
        /* n at 0x44, ncv 0x48, nev 0x4c */
        *(int*)(base+0x44) = n;
        *(int*)(base+0x48) = ncv;
        *(int*)(base+0x4c) = nev;
        *(int*)(base+0x3c) = which; /* guess */
        *(int*)(base+0x40) = bmat;
        *(int*)(base+0x50) = maxiter;
        *(int*)(base+0x54) = mode;
        *(int*)(base+0x60) = 0; /* np? */
    }
    int lworkl = 3*ncv*(ncv+2);
    ARNAUD_dnaupd(&st, resid, v, ipntr, workd, workl, lworkl);

    int ido_out, info_out;
    if (layout==0) { ido_out = st.i[0]; info_out = st.i[3]; }
    else {
        unsigned char *base=(unsigned char*)&st;
        ido_out = *(int*)(base+0x34);
        info_out = *(int*)(base+0x38);
    }
    return Py_BuildValue("ii", ido_out, info_out);
}

static PyMethodDef methods[] = {
    {"call_once", call_once, METH_VARARGS, ""},
    {NULL,NULL,0,NULL}
};
static struct PyModuleDef moduledef = {PyModuleDef_HEAD_INIT, "fast_eigs", NULL, -1, methods};
PyMODINIT_FUNC PyInit_fast_eigs(void) {
    import_array();
    return PyModule_Create(&moduledef);
}
