#define NPY_NO_DEPRECATED_API NPY_1_7_API_VERSION
#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <numpy/arrayobject.h>
#include <string.h>

/* Use scipy's dnaupd_wrap via a thin call? We can't easily. Instead call ARNAUD
   through a function pointer resolved at runtime, but we still need the struct.
   Pragmatic approach: do the matvec in C and drive iteration by calling back
   into a Python-provided dnaupd_wrap? That's slower.
   Here we just provide a fast CSR matvec used by a Python loop, plus an
   in-place version writing into a preallocated output, to cut allocations.
*/

static PyObject *csr_mv(PyObject *self, PyObject *args) {
    PyArrayObject *indptr, *indices, *data, *x, *y;
    if (!PyArg_ParseTuple(args, "OOOOO", &indptr, &indices, &data, &x, &y)) return NULL;
    const int *ip = (const int*)PyArray_DATA(indptr);
    const int *idx = (const int*)PyArray_DATA(indices);
    const double *a = (const double*)PyArray_DATA(data);
    const double *xv = (const double*)PyArray_DATA(x);
    double *yv = (double*)PyArray_DATA(y);
    npy_intp n = PyArray_DIM(indptr, 0) - 1;
    for (npy_intp i = 0; i < n; i++) {
        double s = 0.0;
        int end = ip[i+1];
        for (int j = ip[i]; j < end; j++) s += a[j] * xv[idx[j]];
        yv[i] = s;
    }
    Py_RETURN_NONE;
}

static PyMethodDef methods[] = {
    {"csr_mv", csr_mv, METH_VARARGS, ""},
    {NULL,NULL,0,NULL}
};
static struct PyModuleDef moduledef = {PyModuleDef_HEAD_INIT, "eigs_fast", NULL, -1, methods};
PyMODINIT_FUNC PyInit_eigs_fast(void) {
    import_array();
    return PyModule_Create(&moduledef);
}
