 * ARNAUD_dnaupd(state, resid, v, ipntr, workd, workl, lworkl)
 * state layout (from scipy pack_dict_to_state_d):
 *   0x00 tol (double)
 *   0x08 getv0_rnorm0 .. 0x28 aup2_rnorm (doubles, init 0)
 *   0x30 which (int)   0x34 ido (int)   0x38 info (int)   0x3c bmat (int)
 *   0x40 mode (int)    0x44 n (int)     0x48 ncv (int)    0x4c nev (int)
 *   0x50 shift (int)   0x54 maxiter     0x58 nconv        0x5c iter
 *   0x60 np (int)
 *   0x64..0xbc remaining int counters (init 0)
 */
extern void ARNAUD_dnaupd(void *state, double *resid, double *v, int32_t *ipntr,
                          double *workd, double *workl, int lworkl);

typedef struct {
    unsigned char raw[0xc0];
} State;

static void set_i(State *s, int off, int v) { memcpy(s->raw + off, &v, 4); }
static int get_i(State *s, int off) { int v; memcpy(&v, s->raw + off, 4); return v; }
static void set_d(State *s, int off, double v) { memcpy(s->raw + off, &v, 8); }

static PyObject *eigs_lm(PyObject *self, PyObject *args) {
    PyArrayObject *indptr_a, *indices_a, *data_a, *resid_a, *v_a, *ipntr_a, *workd_a, *workl_a;
    int n, nev, ncv, maxiter, which, bmat, info, mode, shift;
    double tol;
    if (!PyArg_ParseTuple(args, "iiiiidiiiiiOOOOOOOO",
            &n, &nev, &ncv, &maxiter, &which, &tol, &bmat, &info, &mode, &shift,
            &indptr_a, &indices_a, &data_a, &resid_a, &v_a, &ipntr_a, &workd_a, &workl_a))
        return NULL;

    const int32_t *ip = (const int32_t *)PyArray_DATA(indptr_a);
    const int32_t *idx = (const int32_t *)PyArray_DATA(indices_a);
    const double *adata = (const double *)PyArray_DATA(data_a);
    double *resid = (double *)PyArray_DATA(resid_a);
    double *V = (double *)PyArray_DATA(v_a);
    int32_t *ipntr = (int32_t *)PyArray_DATA(ipntr_a);
    double *workd = (double *)PyArray_DATA(workd_a);
    double *workl = (double *)PyArray_DATA(workl_a);
    int lworkl = 3 * ncv * (ncv + 2);

    State st;
    memset(&st, 0, sizeof(st));
    set_d(&st, 0x00, tol);
    set_i(&st, 0x30, which);
    set_i(&st, 0x34, 0);       /* ido */
    set_i(&st, 0x38, info);
    set_i(&st, 0x3c, bmat);
    set_i(&st, 0x40, mode);
    set_i(&st, 0x44, n);
    set_i(&st, 0x48, ncv);
    set_i(&st, 0x4c, nev);
    set_i(&st, 0x50, shift);
    set_i(&st, 0x54, maxiter);

    int guard = maxiter * ncv + 1000;
    for (int it = 0; it < guard; it++) {
        ARNAUD_dnaupd(&st, resid, V, ipntr, workd, workl, lworkl);
        int ido = get_i(&st, 0x34);
        if (ido == 1 || ido == -1 || ido == 5) {
            int xs = ipntr[0];
            int ys = ipntr[1];
            const double *x = workd + xs;
            double *y = workd + ys;
            for (int r = 0; r < n; r++) {
                double s = 0.0;
                int end = ip[r + 1];
                for (int j = ip[r]; j < end; j++) s += adata[j] * x[idx[j]];
                y[r] = s;
            }
        } else if (ido == 2) {
            int xs = ipntr[0], ys = ipntr[1];
            memcpy(workd + ys, workd + xs, (size_t)n * sizeof(double));
        } else if (ido == 4) {
            /* should not happen with info=1 (user supplied start) */
            for (int r = 0; r < n; r++) resid[r] = 1.0;
        } else {
            break;
        }
    }
    int info_out = get_i(&st, 0x38);
    int nconv = get_i(&st, 0x58);
    int iters = get_i(&st, 0x5c);
    int ido = get_i(&st, 0x34);
    return Py_BuildValue("iiii", info_out, nconv, iters, ido);
}

